import { MakeLogicType, afterMount, connect, kea, listeners, path } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { teamLogic } from 'scenes/teamLogic'

import { alertsList } from 'products/alerts/frontend/generated/api'
import type { AlertApi } from 'products/alerts/frontend/generated/api.schemas'

const ALERT_OPTIONS_PAGE_SIZE = 100

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightAlertTriggerOptionsLogicValues {
    currentTeamId: number | null // teamLogic
    alerts: AlertApi[] | null
    alertsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightAlertTriggerOptionsLogicActions {
    loadCurrentTeamSuccess: (
        currentTeam: import('~/types').TeamType | import('~/types').TeamPublicType | null,
        payload?: any
    ) => {
        currentTeam: import('~/types').TeamType | import('~/types').TeamPublicType | null
        payload?: any
    } // teamLogic
    loadAlerts: (_: void) => void
    loadAlertsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadAlertsSuccess: (
        alerts: AlertApi[] | null,
        payload?: void
    ) => {
        alerts: AlertApi[] | null
        payload?: void
    }
}

export type insightAlertTriggerOptionsLogicType = MakeLogicType<
    insightAlertTriggerOptionsLogicValues,
    insightAlertTriggerOptionsLogicActions
>

export const insightAlertTriggerOptionsLogic = kea<insightAlertTriggerOptionsLogicType>([
    path([
        'products',
        'workflows',
        'frontend',
        'Workflows',
        'hogflows',
        'registry',
        'triggers',
        'insightAlertTriggerOptionsLogic',
    ]),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
        actions: [teamLogic, ['loadCurrentTeamSuccess']],
    })),
    loaders(({ values }) => ({
        alerts: [
            null as AlertApi[] | null,
            {
                loadAlerts: async (_: void, breakpoint): Promise<AlertApi[] | null> => {
                    if (!values.currentTeamId) {
                        return null
                    }
                    // Every page, so the picker can offer any alert the person can read, not only the newest.
                    const alerts: AlertApi[] = []
                    for (let offset = 0; ; offset += ALERT_OPTIONS_PAGE_SIZE) {
                        const page = await alertsList(String(values.currentTeamId), {
                            limit: ALERT_OPTIONS_PAGE_SIZE,
                            offset,
                        })
                        // Stops the scan once the panel closes or a newer load starts.
                        breakpoint()
                        alerts.push(...page.results)
                        if (!page.next || page.results.length === 0) {
                            return alerts
                        }
                    }
                },
            },
        ],
    })),
    listeners(({ actions }) => ({
        loadAlertsFailure: ({ error }) => {
            posthog.captureException(error, { scope: 'insightAlertTriggerOptionsLogic.load' })
        },
        // The logic can mount before the team resolves; retry the load once it does.
        loadCurrentTeamSuccess: () => {
            actions.loadAlerts()
        },
    })),
    afterMount(({ actions }) => {
        actions.loadAlerts()
    }),
])
